SELECT YEAR(fecha_venta)   AS anio,       MONTH(fecha_venta)  AS mes,       SUM(cantidad * precio_unitario) AS facturacion,       CASE WHEN SUM(cantidad * precio_unitario) >                 (SELECT AVG(total_mes)                  FROM  (SELECT SUM(cantidad * precio_unitario) AS total_mes                         FROM   ventas                         GROUP BY YEAR(fecha_venta), MONTH(fecha_venta)) t)            THEN 'Por encima'            ELSE 'Por debajo'       END                 AS comparativaFROM   ventasGROUP BY YEAR(fecha_venta), MONTH(fecha_venta)ORDER BY anio, mes;